export function renderLinksPage(): string {
  return `<!DOCTYPE html>
<html lang="ar" dir="rtl">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>سيّر — الروابط</title>
<meta name="description" content="سيّر — طلعتك صارت لعبة. سجّل بقائمة الانتظار.">
<style>
:root{
  --teal:#005854; --teal-deep:#002E2B;
  --falcon:#E8A33D; --falcon-deep:#D08D2B;
}
*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html{background:var(--teal-deep)}
body{
  font-family:-apple-system,"SF Arabic",BlinkMacSystemFont,"Segoe UI",Tahoma,sans-serif;
  background:
    radial-gradient(1100px 700px at 85% -10%, rgba(232,163,61,.14), transparent 60%),
    radial-gradient(900px 700px at -10% 110%, rgba(255,255,255,.06), transparent 55%),
    linear-gradient(168deg,#00635E 0%, var(--teal) 42%, var(--teal-deep) 100%);
  min-height:100vh;display:flex;flex-direction:column;align-items:center;
  padding:52px 20px 32px;color:#fff;position:relative;overflow-x:hidden;
}
/* the calligraphy behind everything */
.mark{position:fixed;pointer-events:none;user-select:none;z-index:0}
.mark-a{width:min(1250px,175vw);top:50%;left:50%;opacity:.075;transform:translate(-50%,-50%) rotate(-8deg)}

.wrap{width:100%;max-width:430px;display:flex;flex-direction:column;align-items:center;position:relative;z-index:1}

@keyframes rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
.r1{animation:rise .5s ease .05s both}
.r2{animation:rise .5s ease .15s both}
.r3{animation:rise .5s ease .25s both}
.r4{animation:rise .5s ease .35s both}
.r5{animation:rise .5s ease .45s both}
@media(prefers-reduced-motion:reduce){.r1,.r2,.r3,.r4,.r5{animation:none}}

.logo{
  width:112px;height:112px;border-radius:32px;overflow:hidden;
  box-shadow:0 16px 40px rgba(0,0,0,.32);
  margin-bottom:18px;
}
.logo img{width:100%;height:100%;display:block}

h1{font-size:30px;font-weight:800;letter-spacing:.5px;text-shadow:0 2px 14px rgba(0,0,0,.25)}
.tag{font-size:15px;color:rgba(255,255,255,.88);margin-top:8px;text-align:center;line-height:1.75}

.links{width:100%;margin-top:28px;display:flex;flex-direction:column;gap:13px}
.btn{
  display:flex;align-items:center;gap:14px;width:100%;
  text-decoration:none;border-radius:19px;padding:17px 18px;
  font-size:16px;font-weight:800;transition:transform .12s;
  position:relative;overflow:hidden;
}
.btn:active{transform:scale(.975)}
.btn .em{font-size:22px;flex-shrink:0}
.btn .tx{flex:1;text-align:right}
.btn .tx small{display:block;font-size:12px;font-weight:600;opacity:.78;margin-top:3px}
.btn .arrow{font-size:16px;opacity:.55;transform:scaleX(-1)}

.btn-primary{
  background:linear-gradient(135deg,var(--falcon),var(--falcon-deep));color:#33230a;
  box-shadow:0 10px 28px rgba(232,163,61,.42);
  animation:breath 2.8s ease-in-out infinite;
}
.btn-primary::after{
  content:"";position:absolute;top:0;bottom:0;width:46%;
  background:linear-gradient(115deg,transparent,rgba(255,255,255,.42),transparent);
  left:-60%;transform:skewX(-18deg);
  animation:sweep 3.6s ease-in-out infinite;
}
@keyframes sweep{0%,55%{left:-60%}85%,100%{left:130%}}
@keyframes breath{0%,100%{box-shadow:0 10px 28px rgba(232,163,61,.42)}50%{box-shadow:0 12px 40px rgba(232,163,61,.68)}}
@media(prefers-reduced-motion:reduce){.btn-primary{animation:none}.btn-primary::after{animation:none;display:none}}

.btn-card{
  background:rgba(255,255,255,.09);
  border:1px solid rgba(255,255,255,.20);color:#fff;
  backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);
  box-shadow:0 6px 20px rgba(0,0,0,.18);
}

.divider{display:flex;align-items:center;gap:12px;width:100%;margin-top:28px;color:rgba(255,255,255,.5);font-size:12px;font-weight:700}
.divider::before,.divider::after{content:"";flex:1;height:1px;background:rgba(255,255,255,.18)}

.socials{display:flex;gap:14px;margin-top:16px}
.soc{
  width:48px;height:48px;border-radius:50%;
  background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.20);
  display:grid;place-items:center;text-decoration:none;font-size:19px;color:#fff;
  transition:transform .12s, background .12s;
}
.soc:active{transform:scale(.9)}
.soc:hover{background:rgba(255,255,255,.16)}

.stores{display:flex;gap:11px;margin-top:24px;width:100%;justify-content:center;flex-wrap:wrap}
.store{
  position:relative;display:flex;align-items:center;gap:11px;
  background:rgba(0,0,0,.42);border:1px solid rgba(255,255,255,.22);
  border-radius:15px;padding:11px 18px;text-decoration:none;color:#fff;
  min-width:158px;transition:transform .12s, background .12s;
}
.store:active{transform:scale(.96)}
.store:hover{background:rgba(0,0,0,.55)}
.store .st{display:flex;flex-direction:column;font-size:16px;font-weight:800;line-height:1.15;text-align:right}
.store .st small{font-size:10.5px;font-weight:600;opacity:.75}
.soon{
  position:absolute;top:-9px;left:12px;font-size:10px;font-weight:800;
  background:var(--falcon);color:#33230a;border-radius:99px;padding:2px 9px;
  box-shadow:0 3px 8px rgba(0,0,0,.3);
}
.langbtn{
  position:fixed;top:16px;inset-inline-end:18px;z-index:5;
  background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.28);
  color:#fff;font-size:13px;font-weight:800;border-radius:99px;padding:8px 16px;
  cursor:pointer;backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);
  font-family:inherit;transition:transform .12s, background .12s;
}
.langbtn:active{transform:scale(.94)}
.langbtn:hover{background:rgba(255,255,255,.2)}
[dir="ltr"] .btn .tx{text-align:left}
[dir="ltr"] .btn .arrow{transform:none}
[dir="ltr"] .store .st{text-align:left}
.foot{margin-top:auto;padding-top:34px;font-size:12px;color:rgba(255,255,255,.5);text-align:center;line-height:1.9}
.foot b{color:rgba(255,255,255,.78)}
</style>
</head>
<body>

<button class="langbtn" id="langBtn" onclick="switchLang()">EN</button>

<img class="mark mark-a" src="data:image/png;base64," alt="">

<div class="wrap">

  <div class="logo r1"><img src="data:image/png;base64," alt="سيّر"></div>

  <h1 class="r2" id="brand">سيّر</h1>
  <p class="tag r2" id="tagline">طلعتك صارت لعبة — امشِ، سجّل حضورك،<br>واكسب قهوتك ☕</p>

  <div class="links">

    <a class="btn btn-primary r3" href="https://saayr.sa" target="_blank" rel="noopener">
      <span class="em">🦅</span>
      <span class="tx" id="txMain">سجّل بقائمة الانتظار<small>كن من أوائل اللاعبين بالرياض</small></span>
      <span class="arrow">→</span>
    </a>

    <a class="btn btn-card r4" href="mailto:Salam@saayr.sa?subject=%D8%A7%D9%86%D8%B6%D9%85%D8%A7%D9%85%20%D9%83%D8%B4%D8%B1%D9%8A%D9%83%20%E2%80%94%20%D8%B3%D9%8A%D9%91%D8%B1">
      <span class="em">🤝</span>
      <span class="tx" id="txMerch">عندك مقهى أو محل؟<small>راسلنا: Salam@saayr.sa</small></span>
      <span class="arrow">→</span>
    </a>

  </div>

  <div class="divider r5" id="divFollow">تابعنا</div>
  <div class="socials r5">
    <a class="soc" href="https://x.com/SaayrApp" target="_blank" rel="noopener" aria-label="X">𝕏</a>
    <a class="soc" href="https://tiktok.com/@SaayrApp" target="_blank" rel="noopener" aria-label="TikTok"><svg viewBox="0 0 24 24" width="20" height="20" fill="#fff"><path d="M12.53.02C13.84 0 15.14.01 16.44 0c.08 1.53.63 3.09 1.75 4.17 1.12 1.11 2.7 1.62 4.24 1.79v4.03c-1.44-.05-2.89-.35-4.2-.97-.57-.26-1.1-.59-1.62-.93-.01 2.92.01 5.84-.02 8.75-.08 1.4-.54 2.79-1.35 3.94-1.31 1.92-3.58 3.17-5.91 3.21-1.43.08-2.86-.31-4.08-1.03-2.02-1.19-3.44-3.37-3.65-5.71-.02-.5-.03-1-.01-1.49.18-1.9 1.12-3.72 2.58-4.96 1.66-1.44 3.98-2.13 6.15-1.72.02 1.48-.04 2.96-.04 4.44-.99-.32-2.15-.23-3.02.37-.63.41-1.11 1.04-1.36 1.75-.21.51-.15 1.07-.14 1.61.24 1.64 1.82 3.02 3.5 2.87 1.12-.01 2.19-.66 2.77-1.61.19-.33.4-.67.41-1.06.1-1.79.06-3.57.07-5.36.01-4.03-.01-8.05.02-12.07z"/></svg></a>
    <a class="soc" href="https://instagram.com/SaayrApp" target="_blank" rel="noopener" aria-label="Instagram"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="#fff" stroke-width="1.9" stroke-linecap="round"><rect x="3" y="3" width="18" height="18" rx="5.2"/><circle cx="12" cy="12" r="4.2"/><circle cx="17.2" cy="6.8" r="1.15" fill="#fff" stroke="none"/></svg></a>
    <a class="soc" href="mailto:Salam@saayr.sa" aria-label="Email"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="#fff" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><rect x="2.5" y="5" width="19" height="14" rx="3"/><path d="m3.5 7 8.5 6 8.5-6"/></svg></a>
  </div>

  <div class="stores r5">
    <a class="store" href="https://saayr.sa" target="_blank" rel="noopener">
      <span class="soon">قريبًا</span>
      <svg viewBox="0 0 24 24" width="24" height="24" fill="#fff"><path d="M16.365 12.44c.03 3.2 2.81 4.27 2.84 4.28-.02.08-.44 1.52-1.46 3-.88 1.28-1.8 2.55-3.24 2.58-1.42.03-1.88-.84-3.5-.84-1.63 0-2.14.81-3.48.87-1.4.05-2.46-1.38-3.35-2.65-1.82-2.63-3.2-7.44-1.34-10.68.93-1.61 2.58-2.63 4.38-2.66 1.37-.03 2.66.92 3.5.92.83 0 2.4-1.14 4.05-.97.69.03 2.63.28 3.87 2.1-.1.06-2.31 1.35-2.27 4.05zM13.6 4.5c.74-.9 1.24-2.14 1.1-3.38-1.07.04-2.36.71-3.12 1.6-.69.8-1.29 2.07-1.13 3.29 1.19.09 2.41-.6 3.15-1.51z"/></svg>
      <span class="st" id="st1"><small>حمّله من</small>App Store</span>
    </a>
    <a class="store" href="https://saayr.sa" target="_blank" rel="noopener">
      <span class="soon">قريبًا</span>
      <svg viewBox="0 0 24 24" width="22" height="22" fill="#fff"><path d="M22.018 13.298l-3.919 2.218-3.515-3.493 3.543-3.521 3.891 2.202a1.49 1.49 0 0 1 0 2.594zM1.337.924a1.486 1.486 0 0 0-.112.568v21.017c0 .217.045.419.124.6l11.155-11.087L1.337.924zm12.207 10.065l3.258-3.238L3.45.195a1.466 1.466 0 0 0-.946-.179l11.04 10.973zm0 2.067l-11 10.933c.298.036.612-.016.906-.183l13.324-7.54-3.23-3.21z"/></svg>
      <span class="st" id="st2"><small>متوفر على</small>Google Play</span>
    </a>
  </div>

  <p class="foot" id="foot"><b>سيّر</b> · صنع بحب في الرياض 🇸🇦<br>saayr.sa</p>

</div>
<script>
var L = {
  ar: {
    brand: "سيّر",
    tagline: "طلعتك صارت لعبة — امشِ، سجّل حضورك،<br>واكسب قهوتك ☕",
    txMain: "سجّل بقائمة الانتظار<small>كن من أوائل اللاعبين بالرياض</small>",
    txMerch: "عندك مقهى أو محل؟<small>راسلنا: Salam@saayr.sa</small>",
    divFollow: "تابعنا",
    st1: "<small>حمّله من</small>App Store",
    st2: "<small>متوفر على</small>Google Play",
    foot: "<b>سيّر</b> · صنع بحب في الرياض 🇸🇦<br>saayr.sa",
    soon: "قريبًا", btn: "EN", dir: "rtl", lang: "ar"
  },
  en: {
    brand: "Saayr",
    tagline: "Your outing just became a game — walk,<br>check in, earn your coffee ☕",
    txMain: "Join the waitlist<small>Be among Riyadh's first players</small>",
    txMerch: "Own a café or shop?<small>Email us: Salam@saayr.sa</small>",
    divFollow: "Follow us",
    st1: "<small>Download on the</small>App Store",
    st2: "<small>Get it on</small>Google Play",
    foot: "<b>Saayr</b> · Made with love in Riyadh 🇸🇦<br>saayr.sa",
    soon: "Soon", btn: "عربي", dir: "ltr", lang: "en"
  }
};
var cur = "ar";
function switchLang(){
  cur = (cur === "ar") ? "en" : "ar";
  var t = L[cur];
  document.documentElement.setAttribute("dir", t.dir);
  document.documentElement.setAttribute("lang", t.lang);
  ["brand","tagline","txMain","txMerch","divFollow","st1","st2","foot"].forEach(function(id){
    document.getElementById(id).innerHTML = t[id];
  });
  document.querySelectorAll(".soon").forEach(function(el){ el.textContent = t.soon; });
  document.getElementById("langBtn").textContent = t.btn;
}
</script>
</body>
</html>`;
}
